import{_ as t,o as r,c as a,a1 as s}from"./chunks/framework.Czc1bIXI.js";const p=JSON.parse('{"title":"General Information","description":"","frontmatter":{"layout":"home","hero":{"name":"FCPLCD","text":"WS 2026/27"}},"headers":[],"relativePath":"26-27/index.md","filePath":"26-27/index.md"}'),d={name:"26-27/index.md"};function c(l,e,o,i,n,h){return r(),a("div",null,[...e[0]||(e[0]=[s('<div class="text-justify"><p>Welcome to the website for the lecture <em>Foundations of Certified Programming Languages and Compiler Design</em>. The two tables below list all lectures and exercises given so far in the winter semester 2026/27. The resources — lecture slides, recordings, code examples, and assignment sheets — are linked in these tables and will be updated as the semester progresses.</p><h1 class="mt-16! mb-8!" id="general-information" tabindex="-1">General Information <a class="header-anchor" href="#general-information" aria-label="Permalink to &quot;General Information {.mt-16! .mb-8!}&quot;">​</a></h1><table><tbody><tr><td><strong>Time slot (lecture)</strong></td><td>Tuesday at 9:20 - 10:50 a.m.</td></tr><tr><td><strong>Time slot (exercise)</strong></td><td>Thursday at 1:00 - 2:30 p.m.</td></tr><tr><td><strong>Room (lecture)</strong></td><td><a href="http://navigator.tu-dresden.de/etplan/apb/00/raum/542100.2060">APB/E001/U</a></td></tr><tr><td><strong>Room (exercise)</strong></td><td><a href="http://navigator.tu-dresden.de/etplan/apb/00/raum/542100.2110">APB/E006/U</a></td></tr></tbody></table></div><h1 class="mt-16! mb-8!" id="lectures" tabindex="-1">Lectures <a class="header-anchor" href="#lectures" aria-label="Permalink to &quot;Lectures {.mt-16! .mb-8!}&quot;">​</a></h1><div class="text-justify"><p>All the relevant lecture materials, including the code shown in the lecture, the exercise sheets and templates as well as the lecture slides, are made available on the lecture&#39;s GitHub repository:</p><p><strong><a href="https://github.com/fcplcd/fcplcd-2026" target="_blank" rel="noreferrer">https://github.com/fcplcd/fcplcd-2026</a></strong><br><br></p></div><table tabindex="0"><thead><tr><th>No.</th><th>Date</th><th>Topic/Slides</th><th>Code</th></tr></thead><tbody><tr><td>0</td><td>20.10.2026</td><td><a href="https://fcplcd.github.io/slidev/26-27/00-motivation" target="_blank" rel="noreferrer">Motivation</a> (<a href="https://github.com/fcplcd/fcplcd-2026/raw/main/lectures/slides/00-motivation.pdf" target="_blank" rel="noreferrer">PDF</a>)</td><td></td></tr><tr><td>1</td><td>27.10.2026</td><td><a href="https://fcplcd.github.io/slidev/26-27/01-logic" target="_blank" rel="noreferrer">Propositional and First-Order Logic</a> (<a href="https://github.com/fcplcd/fcplcd-2026/raw/main/lectures/slides/01-logic.pdf" target="_blank" rel="noreferrer">PDF</a>)</td><td><a href="https://github.com/fcplcd/fcplcd-2026/tree/main/lectures/code/01-logic" target="_blank" rel="noreferrer">code</a></td></tr><tr><td>2</td><td>03.11.2026</td><td><a href="https://fcplcd.github.io/slidev/26-27/02-functional" target="_blank" rel="noreferrer">Functional Programming in Rocq</a> (<a href="https://github.com/fcplcd/fcplcd-2026/raw/main/lectures/slides/02-functional.pdf" target="_blank" rel="noreferrer">PDF</a>)</td><td><a href="https://github.com/fcplcd/fcplcd-2026/tree/main/lectures/code/02-functional" target="_blank" rel="noreferrer">code</a></td></tr><tr><td>3</td><td>10.11.2026</td><td><a href="https://fcplcd.github.io/slidev/26-27/03-semantics" target="_blank" rel="noreferrer">Syntax and Semantics</a> (<a href="https://github.com/fcplcd/fcplcd-2026/raw/main/lectures/slides/03-semantics.pdf" target="_blank" rel="noreferrer">PDF</a>)</td><td><a href="https://github.com/fcplcd/fcplcd-2026/tree/main/lectures/code/03-semantics" target="_blank" rel="noreferrer">code</a></td></tr><tr><td>4</td><td>17.11.2026</td><td><a href="https://fcplcd.github.io/slidev/26-27/04-lambda" target="_blank" rel="noreferrer">The Untyped Lambda Calculus</a> (<a href="https://github.com/fcplcd/fcplcd-2026/raw/main/lectures/slides/04-lambda.pdf" target="_blank" rel="noreferrer">PDF</a>)</td><td><a href="https://github.com/fcplcd/fcplcd-2026/tree/main/lectures/code/04-lambda" target="_blank" rel="noreferrer">code</a></td></tr><tr><td>5</td><td>24.11.2026</td><td><a href="https://fcplcd.github.io/slidev/26-27/05-types" target="_blank" rel="noreferrer">Types</a> (<a href="https://github.com/fcplcd/fcplcd-2026/raw/main/lectures/slides/05-types.pdf" target="_blank" rel="noreferrer">PDF</a>)</td><td><a href="https://github.com/fcplcd/fcplcd-2026/tree/main/lectures/code/05-types" target="_blank" rel="noreferrer">code</a></td></tr></tbody></table><h1 class="mt-16! mb-8!" id="assigments" tabindex="-1">Assigments <a class="header-anchor" href="#assigments" aria-label="Permalink to &quot;Assigments {.mt-16! .mb-8!}&quot;">​</a></h1><div class="text-justify"><p>The course assignments serve to reinforce the lecture material and to acquire practical knowledge of the <a href="https://rocq-prover.org/" target="_blank" rel="noreferrer">Rocq</a> theorem prover. You will generally have two weeks to complete each assignment sheet. The exercise slot in the first week is meant for discussing the assignment and clarifying any problems you run into while working on it. The deadline is typically exactly one day before the second exercise slot, so that we can use the slot in the second week to go through the solution together.</p><p>You can submit your solutions by emailing them to us (<a href="mailto:fcplcd@barkhauseninstitut.org" target="_blank" rel="noreferrer">fcplcd@barkhauseninstitut.org</a>) by the specified due date. You are not required to submit the assignments in order to take the exam. However, we will take your solutions into account when designing your exam questions. This means, for example, that you are more likely to receive specific programming tasks in the exam if we cannot tell from your submissions whether you have learned to program in Rocq.</p></div><table tabindex="0"><thead><tr><th>No.</th><th>Published</th><th>Due</th><th>Assignment</th></tr></thead><tbody><tr><td>1.</td><td>28.10.2026</td><td>04.11.2026</td><td><a href="https://github.com/fcplcd/fcplcd-2026/raw/main/exercises/exercise1/exercise1.pdf" target="_blank" rel="noreferrer">PDF</a> / <a href="https://github.com/fcplcd/fcplcd-2026/blob/main/exercises/exercise1/exercise1.v" target="_blank" rel="noreferrer">code</a> / <a href="./setup.html">How to set up Rocq</a></td></tr><tr><td>2.</td><td>05.11.2026</td><td>18.11.2026</td><td><a href="https://github.com/fcplcd/fcplcd-2026/raw/main/exercises/exercise2/exercise2.pdf" target="_blank" rel="noreferrer">PDF</a> / <a href="https://github.com/fcplcd/fcplcd-2026/blob/main/exercises/exercise2/exercise2.v" target="_blank" rel="noreferrer">code</a> / <a href="https://github.com/fcplcd/fcplcd-2026/raw/main/exercises/exercise2/exercise2-notes.v" target="_blank" rel="noreferrer">notes</a> / <a href="https://github.com/fcplcd/fcplcd-2026/raw/main/exercises/exercise2/notes&#39;.v" target="_blank" rel="noreferrer">notes&#39;</a></td></tr><tr><td>3.</td><td>19.11.2026</td><td>03.12.2026</td><td><a href="https://github.com/fcplcd/fcplcd-2026/raw/main/exercises/exercise3/exercise3.pdf" target="_blank" rel="noreferrer">PDF</a> / <a href="https://github.com/fcplcd/fcplcd-2026/blob/main/exercises/exercise3/exercise3.v" target="_blank" rel="noreferrer">code</a></td></tr></tbody></table>',7)])])}const m=t(d,[["render",c]]);export{p as __pageData,m as default};
